<template><svg class="ui-sparkline" :viewBox="`0 0 ${width} ${height}`" role="img" :aria-label="label"><polyline :points="points" fill="none" :stroke="color" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/></svg></template>
<script setup lang="ts">import{computed}from'vue';const props=withDefaults(defineProps<{values:number[];width?:number;height?:number;color?:string;label?:string}>(),{width:120,height:32,color:'currentColor',label:'趋势'});const points=computed(()=>{if(!props.values.length)return'';const min=Math.min(...props.values),max=Math.max(...props.values),range=max-min||1;return props.values.map((value,index)=>`${(index/(props.values.length-1||1))*props.width},${props.height-((value-min)/range)*(props.height-4)-2}`).join(' ')});</script>
<style scoped>.ui-sparkline{display:block;width:100%;max-width:120px;height:32px;color:var(--ui-text)}</style>
